#pragma once

// The docs.read text compiled from files (docs/scene-api.md and
// scenes/examples) as raw DEFLATE streams: docs_data.cpp, generated by
// tools/gen_agent_docs.py.

#include <cstddef>
#include <cstdint>
#include <span>
#include <string_view>

#include "wisp/base/result.hpp"
#include "wisp/os/large.hpp"

namespace wisp::agent {

// A raw DEFLATE stream and the size of the text it inflates to.
struct PackedText {
    std::span<const uint8_t> deflated;
    size_t size;
};

// docs/scene-api.md, which is schema_markdown().
PackedText scene_api_text();

// The example topics, one after another.
PackedText examples_text();

// An example topic: bytes [offset, offset + size) of examples_text().
struct DocEntry {
    std::string_view topic;
    size_t offset;
    size_t size;
};

// examples, then example/<id>... by id.
std::span<const DocEntry> doc_entries();

// `p`'s text inflated into Mem::Large (docs.cpp). NoMemory when it does
// not fit; InvalidArgument when the stream is corrupt or inflates to
// another size than `p.size`.
Result<os::LargeBuffer> unpack_text(const PackedText& p);

}  // namespace wisp::agent
